local A="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local L={}for I=1,64 do L[A:sub(I,I)]=I-1 end
local T=D:gsub("[^%w+/]","")
local O={}
for I=1,#T,4 do
 local a,b,c,d=T:sub(I,I),T:sub(I+1,I+1),T:sub(I+2,I+2),T:sub(I+3,I+3)
 local n=L[a]*262144+(L[b] or 0)*4096+(L[c] or 0)*64+(L[d] or 0)
 O[#O+1]=string.char(math.floor(n/65536)%256)
 if c~="" then O[#O+1]=string.char(math.floor(n/256)%256) end
 if d~="" then O[#O+1]=string.char(n%256) end
end
return loadstring(table.concat(O))(...)
